#!/usr/bin/env bash
# Question 5: Ingress routes of ${Q5_NS}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

rm -rf /opt/course/audit
mkdir -p /opt/course/audit
chown -R ubuntu:ubuntu /opt/course
kubectl delete namespace "${Q5_NS}-shop" --ignore-not-found --wait=true >/dev/null
kubectl create namespace "${Q5_NS}-shop" >/dev/null 2>&1 || kubectl get namespace "${Q5_NS}-shop" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}-shop' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl delete namespace "${Q5_NS}-blog" --ignore-not-found --wait=true >/dev/null
kubectl create namespace "${Q5_NS}-blog" >/dev/null 2>&1 || kubectl get namespace "${Q5_NS}-blog" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q5_NS}-blog' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
region=$(shuf -e eu us apac -n 1)
missing=$(shuf -e shop-api admin-ui blog -n 1)
kubectl apply -f - <<EOF >/dev/null
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata: { name: storefront, namespace: ${Q5_NS}-shop }
spec:
  rules:
    - host: shop-$region.lab
      http:
        paths:
          - { path: /, pathType: Prefix, backend: { service: { name: storefront, port: { number: 80 } } } }
          - { path: /api, pathType: Prefix, backend: { service: { name: shop-api, port: { number: 8080 } } } }
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata: { name: admin, namespace: ${Q5_NS}-shop }
spec:
  rules:
    - host: admin-$region.lab
      http:
        paths:
          - { path: /, pathType: Prefix, backend: { service: { name: admin-ui, port: { name: http } } } }
---
apiVersion: networking.k8s.io/v1
kind: Ingress
metadata: { name: blog, namespace: ${Q5_NS}-blog }
spec:
  rules:
    - host: blog-$region.lab
      http:
        paths:
          - { path: /, pathType: Prefix, backend: { service: { name: blog, port: { number: 80 } } } }
    - host: www.blog-$region.lab
      http:
        paths:
          - { path: /, pathType: Prefix, backend: { service: { name: blog, port: { number: 80 } } } }
EOF
# Every backend Service exists, except one.
for s in shop/storefront:80 shop/shop-api:8080 shop/admin-ui:80 blog/blog:80; do
  ns="${Q5_NS}-${s%%/*}" rest=${s#*/}
  name=${rest%%:*} port=${rest#*:}
  [[ "$name" == "$missing" ]] && continue
  kubectl -n "$ns" create service clusterip "$name" --tcp="$port:$port" >/dev/null
done
: "${Q5_NS}"
